(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const btns = Array.from(document.querySelectorAll('button')).filter(b => /send\s*otp/i.test((b.innerText||'').replace(/\s+/g,' ')));
  let clicked = 0;
  for (const b of btns) {
    if (b.offsetParent !== null) { b.click(); clicked++; break; }
  }
  await sleep(3500);
  const toasts = Array.from(document.querySelectorAll('div')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/sent|resend|second|otp|number|email|register/i.test(t) && t.length<120).filter((v,i,a)=>a.indexOf(v)===i).slice(0,8);
  const after = Array.from(document.querySelectorAll('button')).map(b=>(b.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/send|otp|resend|\d+s/i.test(t)).slice(0,6);
  return JSON.stringify({clicked, toasts, after});
})()
